// Step 4 — Automated Critic & Redaction Gate (deterministic; mirrors run-pipeline-verify.mjs).
const md = String($json.advisory || $json.body?.advisory || '');
const LEAKS = [
  ['JWT', /eyJ[A-Za-z0-9_-]{6,}\.[A-Za-z0-9_-]{6,}\.[A-Za-z0-9_-]{4,}/],
  ['RFC1918 IP', /\b(?:10\.\d{1,3}\.\d{1,3}\.\d{1,3}|192\.168\.\d{1,3}\.\d{1,3}|172\.(?:1[6-9]|2\d|3[01])\.\d{1,3}\.\d{1,3})\b/],
  ['Bearer', /Bearer\s+[A-Za-z0-9._-]{10,}/i],
  ['Secret prefix', /\b(?:sk-ant-|sk_live_|whsec_|stg_whk_)[A-Za-z0-9_-]{6,}/],
  ['SHA-256 HMAC', /\b[0-9a-f]{64}\b/],
  ['MSISDN', /\b09\d{9}\b/],
];
const SECTIONS = [/## 1\. Metadata & CVSS v3\.1/, /## 2\. Executive Summary/, /## 3\. Root Cause & Attack Surface/, /## 4\. (?:Proof-of-Concept|PoC).*Reproduction/i, /## 5\. Remediation Diff/, /## 6\. Secret & Factuality Audit/];
const leaks = LEAKS.filter(([, re]) => re.test(md)).map(([n]) => n);
const missing = SECTIONS.filter((re) => !re.test(md)).length;
const hasVector = /CVSS:3\.1\/AV:[NALP]\/AC:[LH]\/PR:[NLH]\/UI:[NR]\/S:[UC]\/C:[NLH]\/I:[NLH]\/A:[NLH]/.test(md);
const pass = leaks.length === 0 && missing === 0 && hasVector;
return [{ json: { pass, leaks, missing_sections: missing, cvss_vector_valid: hasVector, advisory: pass ? md : null } }];
